<template><div><SuperModal v-if="show" :blacklist="blacklist" @restore="restoreWord"/><Controls @answered="handle"/></div></template>
<script>
import Controls from './components/Controls.vue';
import SuperModal from './components/SuperModal.vue';
export default{
components:{Controls,SuperModal},
data(){return{blacklist:JSON.parse(localStorage.getItem('readingBlacklist')||'[]'),show:true}},
methods:{restoreWord(w){this.blacklist=this.blacklist.filter(x=>x!==w);localStorage.setItem('readingBlacklist',JSON.stringify(this.blacklist));},
handle(){}}}
</script>